/**
 * issue #74: restores Node-RED's standard module-resource serving
 * capability (`GET /resources/<module>/<file>`) on a headless runner ("B")
 * that boots with `disableEditor: true` and therefore never mounts
 * `@node-red/editor-api`'s editor Express app - the ONLY place stock
 * Node-RED registers this route
 * (`@node-red/editor-api/lib/editor/index.js`'s
 * `editorApp.get(/^\/resources\/((?:@[^\/]+\/)?[^\/]+)\/(.+)$/, ui.moduleResource)`).
 *
 * This module does not reimplement resource resolution. It is a thin
 * Express route wrapper around the SAME public runtime API the stock
 * handler delegates to - `runtime.nodes.getModuleResource({user, module,
 * path})` (`@node-red/runtime/lib/api/nodes.js`, which itself only ever
 * resolves paths already registered by `@node-red/registry`'s
 * `localfilesystem` loader from a module's own `resources/` directory -
 * see `registry.js`'s `getModuleResource()`: any path escaping that
 * directory via `..` is rejected before this route ever runs). No
 * arbitrary filesystem reads, no editor-only route bundle, no Dashboard-
 * specific conditionals - mirrors `ui.js`'s `moduleResource` handler's
 * exact response/error semantics (Content-Type via `mime.getType`, 404 when
 * nothing is found).
 */

"use strict";

const mime = require("mime");

/** Identical regex to the stock editor route: `package` or `@scope/package`. */
const ROUTE_PATTERN = /^\/resources\/((?:@[^/]+\/)?[^/]+)\/(.+)$/;

/**
 * @param {object} options
 * @param {object} options.nodes - the runtime's node registry API, i.e.
 *   `@node-red/runtime`'s `.nodes` (exposes `getModuleResource`).
 * @returns {{pattern: RegExp, handler: function(req,res)}}
 */
function createModuleResourceRoute(options) {
    options = options || {};
    const nodesApi = options.nodes;
    if (!nodesApi || typeof nodesApi.getModuleResource !== "function") {
        throw new Error("createModuleResourceRoute requires options.nodes (the runtime's node registry API, exposing getModuleResource)");
    }

    function handler(req, res) {
        const resourcePath = req.params[1];
        const opts = {
            user: req.user,
            module: req.params[0],
            path: resourcePath
        };
        nodesApi.getModuleResource(opts).then((data) => {
            if (data) {
                res.set("Content-Type", mime.getType(resourcePath));
                res.send(data);
            } else {
                res.status(404).end();
            }
        }).catch((err) => {
            res.status(err && err.status || 500).end();
        });
    }

    return { pattern: ROUTE_PATTERN, handler };
}

module.exports = {
    ROUTE_PATTERN,
    createModuleResourceRoute
};
